from __future__ import annotations

import copy
import json
from collections.abc import AsyncIterator
from typing import TYPE_CHECKING, Any

import structlog
from pydantic import ValidationError

from rasa.builder.copilot.models import EventContent
from rasa.builder.copilot.pydantic_ai import ag_ui_events
from rasa.builder.copilot.pydantic_ai.hooks import build_commit_hook
from rasa.builder.copilot.pydantic_ai.model_registry import validate_model
from rasa.builder.copilot.pydantic_ai.types import (
    Message,
    ReasoningEffort,
    RunRequest,
    ThinkingPref,
)

if TYPE_CHECKING:
    from rasa.builder.copilot.pydantic_ai.agent import (
        PydanticAICopilot,
        TrackerContextResolver,
    )
    from rasa.builder.project_generator import ProjectGenerator

structlogger = structlog.get_logger()


def encode_sse_event(event: dict[str, Any]) -> str:
    """Encode one AG-UI event as an SSE data frame (data-only lines)."""
    return f"data: {json.dumps(event, separators=(',', ':'))}\n\n"


async def stream_copilot_v2_sse(
    runtime: PydanticAICopilot,
    payload: dict[str, Any] | RunRequest,
    project_generator: "ProjectGenerator",
    email: str,
    *,
    tracker_context_resolver: "TrackerContextResolver | None" = None,
) -> AsyncIterator[str]:
    """Convert an AG-UI request payload into SSE frames.

    Wires the Copilot v2 end-of-run hook (commit changed files) so the web
    layer only supplies request-scoped dependencies, not runtime behavior.

    ``payload`` is either a raw AG-UI ``RunAgentInput`` mapping or an already
    parsed ``RunRequest``. Hosts that inspect the request before the agent loop
    runs — a policy pre-flight, a router — parse it once with
    ``parse_run_request`` and pass the result straight through.
    """
    if isinstance(payload, RunRequest):
        run_request = payload
    else:
        try:
            run_request = parse_run_request(payload)
        except (KeyError, TypeError, ValueError) as exc:
            yield encode_sse_event(
                ag_ui_events.run_error(str(exc), code=type(exc).__name__)
            )
            return

    # The project directory is owned by the server, never the client: the file
    # tools and the commit hook must operate on the same path to avoid writing
    # one directory while committing another.
    project_path = str(project_generator.project_folder)
    end_of_run_hook = build_commit_hook(project_generator, email)
    async for event in runtime.stream_ag_ui_events(
        run_request,
        project_path=project_path,
        end_of_run_hook=end_of_run_hook,
        tracker_context_resolver=tracker_context_resolver,
    ):
        yield encode_sse_event(event)


def parse_run_request(payload: dict[str, Any]) -> RunRequest:
    """Parse an AG-UI RunAgentInput-shaped payload.

    Args:
        payload: Raw request body, snake_case or camelCase ids.

    Returns:
        The typed run request. Messages with a role the runtime doesn't drive,
        or with blank content, are dropped.

    Raises:
        KeyError: If ``thread_id``/``run_id`` is missing.
        TypeError: If ``messages`` is not a list.
        ValueError: If the requested model names an unsupported provider.
    """
    raw_messages = payload.get("messages", [])
    if not isinstance(raw_messages, list):
        raise TypeError("messages must be a list")

    messages = tuple(
        Message(role=str(msg["role"]), content=str(msg.get("content", "")))
        for msg in raw_messages
        if str(msg.get("role", "")) in {"user", "assistant", "system"}
        and str(msg.get("content", "")).strip()
    )
    raw_state = payload.get("state", {})
    state: dict[str, Any] = dict(raw_state) if isinstance(raw_state, dict) else {}

    thread_id = payload.get("thread_id", payload.get("threadId"))
    run_id = payload.get("run_id", payload.get("runId"))
    if thread_id is None:
        raise KeyError("thread_id")
    if run_id is None:
        raise KeyError("run_id")

    return RunRequest(
        thread_id=str(thread_id),
        run_id=str(run_id),
        messages=messages,
        state=state,
        model=_parse_model(state),
        thinking=_parse_thinking(state),
        session_id=_parse_session_id(state),
        attachments=_parse_attachments(state),
    )


def _parse_model(state: dict[str, Any]) -> str | None:
    """Extract and validate the requested model id from AG-UI run state.

    Raises:
        ValueError: If the model id names a provider Copilot v2 won't drive.
    """
    model = state.get("model")
    if model is None:
        return None
    model_str = str(model).strip()
    if not model_str:
        return None
    return validate_model(model_str)


def _parse_thinking(state: dict[str, Any]) -> ThinkingPref:
    """Extract thinking preferences from AG-UI run state."""
    raw = state.get("thinking")
    if not isinstance(raw, dict):
        return ThinkingPref()

    # Enable only on a real JSON boolean ``true``. A stringy ``"false"`` would be
    # truthy under ``bool()``, so fail closed on anything that isn't literally
    # ``True`` (the frontend sends a JSON boolean).
    enabled = raw.get("enabled") is True
    budget_raw = raw.get("budget", ThinkingPref().budget)
    try:
        budget = int(budget_raw)
    except (TypeError, ValueError):
        budget = ThinkingPref().budget

    effort_raw = str(raw.get("effort", ReasoningEffort.MEDIUM.value))
    try:
        effort = ReasoningEffort(effort_raw)
    except ValueError:
        effort = ReasoningEffort.MEDIUM
    return ThinkingPref(enabled=enabled, budget=budget, effort=effort)


def _parse_session_id(state: dict[str, Any]) -> str | None:
    """Extract the Inspector session id from AG-UI run state.

    Coerces defensively like ``_parse_model``: whitespace-only degrades to
    ``None`` immediately instead of round-tripping the tracker store.
    """
    session_id = state.get("session_id")
    if session_id is None:
        return None
    session_id_str = str(session_id).strip()
    return session_id_str or None


def _parse_attachments(state: dict[str, Any]) -> tuple[EventContent, ...]:
    """Extract tracker-event attachments from AG-UI run state.

    Each entry is the exact ``{type: "event", ...rawEvent}`` object v1 puts in
    ``message.content``. Malformed entries are dropped individually with a
    warning — a bad attachment must never abort the run. An unhandled
    ``ValidationError`` (a ``ValueError`` subclass) would turn the whole run
    into RUN_ERROR, and a non-dict raises ``AttributeError``, which escapes
    the caller's catch tuple entirely.
    """
    raw_attachments = state.get("attachments")
    if not isinstance(raw_attachments, list):
        return ()

    attachments: list[EventContent] = []
    dropped_count = 0
    for raw_attachment in raw_attachments:
        try:
            # EventContent's before-validator mutates its input in place;
            # deep-copy so the dicts still referenced by RunRequest.state
            # stay intact.
            attachments.append(
                EventContent.model_validate(copy.deepcopy(raw_attachment))
            )
        except (ValidationError, AttributeError, TypeError):
            dropped_count += 1
    if dropped_count:
        structlogger.warning(
            "copilot_v2.parse_attachments.dropped_malformed_entries",
            dropped_count=dropped_count,
            attachment_count=len(raw_attachments),
        )
    return tuple(attachments)
